// Generated by server/demo.js (replay mode): the recorded world world_v2.js with the witness positions the reviewer
// confirmed on the review screen. Only witnesses moved there are overridden; everything else is the recorded output.
import base from './world_v2.js';
export * from './world_v2.js';
const OVERRIDES = {"wit_B":{"x":15,"z":15.6,"movedBy":6.7}};
export default function (...args) {
  const world = base(...args);
  for (const w of world.witnesses || []) {
    const o = OVERRIDES[w.id];
    if (!o) continue;
    const y = Array.isArray(w.position) ? w.position[1] : 0;
    w.recordedPosition = Array.isArray(w.position) ? w.position.slice() : null;
    w.position = [o.x, y, o.z];
    w.confirmedPosition = true;
  }
  return world;
}
